 * @name scwin.popZipCode
 * @author Inswave
 * @date 2026. 09. 29
 * @param _tpCd
 * @returns
 * @hidden N
*/
scwin.popZipCode = async function (_tpCd) {
    /* sdd-asis-lifecycle:begin fn_PopZipCode — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.selFrm = $c.util.getComponent('elwCorpDisclsChrgForm' + _tpCd);
    const zipSearchURL = '/jldinf90009/jldinf90009.xml';
    scwin.setZipCode_recv(await $c.win.openPopup((function (__u) { var __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(zipSearchURL), { id: "zipWin", scrollbars: false, resizable: false, width: "445", height: "600", type: "pageFramePopup" }, Object.assign({ method: "loadInitPage" }, { selFrm: (typeof scwin.selFrm !== 'undefined' ? scwin.selFrm : undefined) })));
    /* sdd-asis-lifecycle:end */
};


